/**
 * Runs the isolation-level suite while every spill check reports memory pressure, as happens when the JVM sees high GC
 * load or low free heap. Snapshot reads that mutate per observed row create one changeset per mutation; compressing
 * them must not allocate an overflow store per changeset, or a 4 GB heap runs out.
 */
public class LmdbStoreIsolationUnderMemoryPressureTest extends LmdbStoreIsolationLevelTest {

	private int previousMinimum;

	@BeforeEach
	void reportMemoryPressureOnEveryCheck() {
		previousMinimum = AbstractMemoryOverflowModel.MIN_AVAILABLE_MEM_BEFORE_OVERFLOWING;
		AbstractMemoryOverflowModel.MIN_AVAILABLE_MEM_BEFORE_OVERFLOWING = Integer.MAX_VALUE;
	}

	@AfterEach
	void restoreSpillThreshold() {
		AbstractMemoryOverflowModel.MIN_AVAILABLE_MEM_BEFORE_OVERFLOWING = previousMinimum;
	}
}
